    next if $rest =~ /^func\s+/;
    next if $rest =~ /\btype\s+\Q$sym\E\b/;
    # must be qualified with declaring package OR import alias from same dir
    my $imports = file_imports($file);
    my $matched = 0;
    # direct pkg.Sym
    if ($rest =~ /\b\Q$d->{pkg}\E\.\Q$sym\E\b/) { $matched=1; }
    else {
