use strict; use warnings;
my $repo = "/bench/repo";

# collect all func/method decls in internal non-test
my @decls;
sub walk {
  my ($dir) = @_;
  opendir(my $d, $dir) or return;
  for my $f (readdir $d) {
    next if $f =~ /^\./;
    my $p = "$dir/$f";
    if (-d $p) { walk($p); next; }
    next unless $f =~ /\.go$/ && $f !~ /_test\.go$/;
    my $rel = $p; $rel =~ s|^\Q$repo/||;
    open my $fh, "<", $p or next;
    my $pkg; while (<$fh>) { if (/^package\s+(\w+)/){$pkg=$1; last} }
    seek $fh,0,0; local $/; my $c=<$fh>; close $fh;
    while ($c =~ /^func\s+(?:\((\w+)\s+\*?(\w+)\)\s+)?(\w+)\s*\(/mg) {
      my ($recv,$rtype,$name)=($1,$2,$3);
      my $sym = $recv ? "$rtype.$name" : $name;
      push @decls, {path=>$rel, pkg=>$pkg, name=>$name, recv=>$rtype, sym=>$sym, exported=>($name=~/^[A-Z]/)};
    }
  }
  closedir $d;
}
walk("$repo/internal");

# For each decl, count call sites in non-test go files
# Pattern: .Name( for methods, Name( or pkg.Name( for funcs
my @results;
for my $d (@decls) {
  my $name = $d->{name};
  my $pat;
  if ($d->{recv}) {
    $pat = "\\.${name}\\s*\\(";
  } else {
    $pat = "\\b${name}\\s*\\(";
  }
  my @lines = qx(grep -r --include=*.go -P -n '$pat' $repo 2>/dev/null);
  my %files; my $n=0;
  for my $line (@lines) {
    chomp $line;
    my ($file, $lineno, $rest) = split /:/, $line, 3;
    next if $file =~ /_test\.go$/;
    next if $file =~ m|/internal/testutil/|;
    # skip declaration line in same symbol
    next if $rest =~ /^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/;
    next if $rest =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
    $n++;
    (my $f=$file)=~s|^\Q$repo/||; $files{$f}=1;
  }
  push @results, [$n, scalar(keys %files), $d->{sym}, $d->{path}, $d->{exported}? "exp":"unexp"] if $n>0;
}
@results = sort { $b->[0] <=> $a->[0] || $b->[1] <=> $a->[1] } @results;
for (@results[0..49]) { printf "%d\t%d\t%s\t%s\t%s\n", @$_; }
'

